// Validate invoice data
const invoice = $input.first().json.data;
let errors = [];
let warnings = [];

// Check if line items total matches subtotal
if (invoice.lineItems && invoice.lineItems.length > 0) {
  const calculatedSubtotal = invoice.lineItems.reduce((sum, item) => sum + (item.amount || 0), 0);
  if (Math.abs(calculatedSubtotal - (invoice.subtotal || 0)) > 0.01) {
    warnings.push(`Line items total ($${calculatedSubtotal.toFixed(2)}) doesn't match subtotal ($${(invoice.subtotal || 0).toFixed(2)})`);
  }
}

// Validate total calculation
const calculatedTotal = (invoice.subtotal || 0) + (invoice.tax || 0);
if (Math.abs(calculatedTotal - invoice.total) > 0.01) {
  warnings.push(`Calculated total ($${calculatedTotal.toFixed(2)}) doesn't match invoice total ($${invoice.total.toFixed(2)})`);
}

// Check required fields
if (!invoice.invoiceNumber) errors.push('Missing invoice number');
if (!invoice.vendor?.name) errors.push('Missing vendor name');
if (!invoice.total) errors.push('Missing total amount');

// Format line items for Google Sheets
const itemsSummary = invoice.lineItems && invoice.lineItems.length > 0
  ? invoice.lineItems.map(item => `${item.description}: ${item.quantity || 1} x $${item.unitPrice || item.amount}`).join('; ')
  : 'No items listed';

// Status is TRUE if valid (no errors), FALSE if invalid (has errors)
const isValid = errors.length === 0;

return [{
  json: {
    invoice: invoice,
    Status: isValid,
    errors: errors,
    warnings: warnings,
    itemsSummary: itemsSummary,
    processedAt: new Date().toISOString(),
    fileName: $('Google Drive Trigger').item.json.name
  }
}];

